struct Photo: Identifiable {
    let id: Int
}
struct GalleryScreen: View {
    @State private var photos = (1...20).map { Photo(id: $0) }
    @State private var isLoading = false
    var body: some View {
        List(photos) { photo in
            Text("Фото \(photo.id)")
                .task {
                    guard photo.id == photos.last?.id else { return }
                    if isLoading { return }
                    await loadMore()
                }
        }
    }
    func loadMore() async {
        isLoading = true
        try? await Task.sleep(for: .seconds(1))
        let start = photos.count + 1
        photos += (start..<start + 20).map { Photo(id: $0) }
        isLoading = false
    }
}

Строки `List` ленивые: `.task` строки запускается, когда она выезжает на экран, и снова — при каждом возвращении прокруткой. Проверка `photos.last?.id` оставляет загрузку только последней строке, а `isLoading` не даёт запустить вторую порцию, пока первая в пути. Без проверок каждая строка при каждом появлении звала бы `loadMore()`.

